class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}
        self.order = []

    def get(self, key):
        if key not in self.data:
            return -1
        # Refresh recency: move the key to the end of the order list
        self.order.remove(key)
        self.order.append(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            # Update existing key: remove old position to refresh recency
            self.order.remove(key)
        elif len(self.data) >= self.capacity:
            # Evict the least recently used key (the first element in order)
            oldest = self.order.pop(0)
            del self.data[oldest]

        self.data[key] = value
