def topological_sort(graph):
    visited = set()
    path = set()
    order = []

    def visit(node):
        if node in path:
            raise ValueError('cycle detected')
        if node in visited:
            return

        path.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)

        path.remove(node)
        visited.add(node)
        order.append(node)

    # We must ensure we consider all nodes, even those that 
    # might only appear as a dependency and not as a key.
    all_nodes = set(graph.keys())
    for dependencies in graph.values():
        for dep in dependencies:
            all_nodes.add(dep)

    for node in all_nodes:
        if node not in visited:
            visit(node)

    return order
