def is_balanced(s):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    opening = {'(', '[', '{'}

    for c in s:
        if c in opening:
            stack.append(c)
        elif c in mapping:
            if not stack or stack.pop() != mapping[c]:
                return False

    return len(stack) == 0
